// The question data for the grade this browser is grading.
//
// Hand-written. The per-grade files it chooses between are GENERATED by
// tools/build-data.mjs from each grade's CSV:
//   grade1.js  <- Grade 1 Standards.csv
//   gradeK.js  <- Kinder Standards.csv
//
// Every view imports from here, so none of them needs to know about grades.

import { GRADE } from "../grade.js";
import * as grade1 from "./grade1.js";
import * as gradeK from "./gradeK.js";

const DATA = GRADE.id === "K" ? gradeK : grade1;

export const QUESTIONS = DATA.QUESTIONS;
export const ASSESSMENTS = DATA.ASSESSMENTS;
export const UNITS = DATA.UNITS;
export const ALL_STANDARD_CODES = DATA.ALL_STANDARD_CODES;
export const INCLUDED_ASSESSMENT_KEYS = DATA.INCLUDED_ASSESSMENT_KEYS;
export const QUESTIONS_BY_ID = DATA.QUESTIONS_BY_ID;
